let pts;

function setup() {
	createCanvas(600, 600);

	pts = [];
	for (let i = 0; i < 3; i++) {
		const x = random(width);
		const s = random(width * 0.1, width * 0.3)
		const y = height/2; // random(height, height *2);
		const dy = random(1, 3);
		const va = random(width)
		const vb = random(width)
		const vc = random(width)
		const vd = random(width)
		const ve = random(width)
		const vf = random(width)
		const vg = random(width)
		const vh = random(width)
		const vi = random(width)
		const vj = random(width)
		const vk = random(width)
		const vl = random(width)
		const vm = random(width)
		const vn = random(width)
		const v = {va, vb, vc, vd, ve, vf, vg, vh, vi, vj, vk, vl, vm, vn}
		pts.push({x, y, s, dy, v})
	}
}


